package com.temporosssolo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TemporossSoloHelperPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TemporossSoloHelperPlugin.class);
		RuneLite.main(args);
	}
}

package com.temporosssolo;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class TemporossRouteTest
{
	@Test
	public void followsCompleteCatch26Route()
	{
		TemporossRoute route = new TemporossRoute();
		assertEquals(TemporossMethod.NO_COOKING_MAX_XP, route.getMethod());
		assertEquals(RouteStage.CATCH_26, route.getStage());

		updateAndAssert(route, snapshot(26, 100, false, false), RouteStage.LOAD_26);
		updateAndAssert(route, snapshot(0, 100, false, false), RouteStage.CATCH_27_FIRST);
		updateAndAssert(route, snapshot(27, 100, false, false), RouteStage.LOAD_27_FIRST);
		updateAndAssert(route, snapshot(0, 100, false, false), RouteStage.ATTACK_FIRST);
		updateAndAssert(route, snapshot(0, 75, true, false), RouteStage.ATTACK_FIRST);
		updateAndAssert(route, snapshot(0, 70, false, false), RouteStage.CATCH_27_SECOND);
		updateAndAssert(route, snapshot(27, 70, false, false), RouteStage.LOAD_THREE);
		updateAndAssert(route, snapshot(24, 70, true, false), RouteStage.ATTACK_TO_TEN);
		updateAndAssert(route, snapshot(24, 10, true, false), RouteStage.LOAD_REMAINDER);
		updateAndAssert(route, snapshot(0, 10, false, false), RouteStage.CATCH_27_FINAL);
		updateAndAssert(route, snapshot(27, 10, false, false), RouteStage.LOAD_FINAL);
		updateAndAssert(route, snapshot(0, 10, true, false), RouteStage.KILL_TEMPOROSS);
		updateAndAssert(route, snapshot(0, 0, false, true), RouteStage.COMPLETE);
	}

	@Test
	public void progressesThroughFishingAndFirstAttack()
	{
		TemporossRoute route = new TemporossRoute();
		assertEquals(RouteStage.CATCH_26, route.getStage());

		route.update(snapshot(26, 100, false, false));
		assertEquals(RouteStage.LOAD_26, route.getStage());

		route.update(snapshot(0, 100, false, false));
		assertEquals(RouteStage.CATCH_27_FIRST, route.getStage());

		route.update(snapshot(27, 100, false, false));
		assertEquals(RouteStage.LOAD_27_FIRST, route.getStage());

		route.update(snapshot(0, 100, false, false));
		assertEquals(RouteStage.ATTACK_FIRST, route.getStage());

		route.update(snapshot(0, 80, true, false));
		assertEquals(RouteStage.ATTACK_FIRST, route.getStage());

		route.update(snapshot(0, 70, false, false));
		assertEquals(RouteStage.CATCH_27_SECOND, route.getStage());
	}

	@Test
	public void firstCatchUsesAvailableInventoryCapacity()
	{
		assertEquals(25, TemporossRoute.getFirstFishTarget(snapshotWithFreeSlots(0, 25)));
		assertEquals(26, TemporossRoute.getFirstFishTarget(snapshotWithFreeSlots(0, 26)));

		TemporossRoute twentySixRoute = new TemporossRoute();
		twentySixRoute.update(snapshotWithFreeSlots(25, 1));
		assertEquals(RouteStage.CATCH_26, twentySixRoute.getStage());
		twentySixRoute.update(snapshotWithFreeSlots(26, 0));
		assertEquals(RouteStage.LOAD_26, twentySixRoute.getStage());

		TemporossRoute twentyFiveRoute = new TemporossRoute();
		twentyFiveRoute.update(snapshotWithFreeSlots(24, 1));
		assertEquals(RouteStage.CATCH_26, twentyFiveRoute.getStage());
		twentyFiveRoute.update(snapshotWithFreeSlots(25, 0));
		assertEquals(RouteStage.LOAD_26, twentyFiveRoute.getStage());

		TemporossRoute fullAtTwentyFour = new TemporossRoute();
		fullAtTwentyFour.update(snapshotWithFreeSlots(24, 0));
		assertEquals(RouteStage.CATCH_26, fullAtTwentyFour.getStage());
	}

	@Test
	public void noCookingMethodStillCountsCrystallisedFish()
	{
		TemporossRoute route = new TemporossRoute();
		RouteSnapshot mixedFish = new RouteSnapshot(
			13,
			0,
			13,
			0,
			100,
			false,
			false,
			false,
			false);

		route.update(mixedFish);
		assertEquals(RouteStage.LOAD_26, route.getStage());
	}

	@Test
	public void waitsForThreeFishAndTenPercentBreakpoints()
	{
		TemporossRoute route = new TemporossRoute();
		while (route.getStage() != RouteStage.LOAD_THREE)
		{
			route.next();
		}

		route.update(snapshot(25, 50, true, false));
		assertEquals(RouteStage.LOAD_THREE, route.getStage());
		route.update(snapshot(24, 50, true, false));
		assertEquals(RouteStage.ATTACK_TO_TEN, route.getStage());

		route.update(snapshot(24, 11, true, false));
		assertEquals(RouteStage.ATTACK_TO_TEN, route.getStage());
		route.update(snapshot(24, 10, true, false));
		assertEquals(RouteStage.LOAD_REMAINDER, route.getStage());
	}

	@Test
	public void recoversWhenMoreThanThreeFishAreLoaded()
	{
		TemporossRoute route = new TemporossRoute();
		while (route.getStage() != RouteStage.LOAD_THREE)
		{
			route.next();
		}

		route.update(snapshot(23, 50, true, false));
		assertEquals(RouteStage.ATTACK_TO_TEN, route.getStage());
	}

	@Test
	public void finishesAfterVictory()
	{
		TemporossRoute route = new TemporossRoute();
		while (route.getStage() != RouteStage.KILL_TEMPOROSS)
		{
			route.next();
		}

		route.update(snapshot(0, 0, false, false));
		assertEquals(RouteStage.KILL_TEMPOROSS, route.getStage());
		route.update(snapshot(0, 0, false, true));
		assertEquals(RouteStage.COMPLETE, route.getStage());
	}

	@Test
	public void manualNavigationStopsAtBounds()
	{
		TemporossRoute route = new TemporossRoute();
		route.previous();
		assertEquals(RouteStage.CATCH_26, route.getStage());

		for (int i = 0; i < route.getStageCount() + 2; i++)
		{
			route.next();
		}
		assertEquals(RouteStage.COMPLETE, route.getStage());
	}

	private static RouteSnapshot snapshot(
		int fish,
		Integer essence,
		boolean poolActive,
		boolean defeated)
	{
		return new RouteSnapshot(
			fish,
			0,
			0,
			Math.max(0, TemporossRoute.FIRST_FISH_TARGET - fish),
			essence,
			false,
			poolActive,
			false,
			defeated);
	}

	private static RouteSnapshot snapshotWithFreeSlots(int fish, int freeInventorySlots)
	{
		return new RouteSnapshot(fish, 0, 0, freeInventorySlots, 100, false, false, false, false);
	}

	private static void updateAndAssert(
		TemporossRoute route,
		RouteSnapshot snapshot,
		RouteStage expectedStage)
	{
		route.update(snapshot);
		assertEquals(expectedStage, route.getStage());
	}
}

package com.temporosssolo;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TemporossCookingRouteTest
{
	private static final int FIRST_HOPPER = 101;
	private static final int SECOND_HOPPER = 202;

	@Test
	public void followsCompleteSeventeenStepCookingRoute()
	{
		TemporossRoute route = new TemporossRoute(TemporossMethod.COOKING_MIX_XP_PERMITS);
		assertEquals(RouteStage.MIX_FISH_17, route.getStage());
		assertEquals(17, route.getStageCount());

		updateAndAssert(route, snapshot(8, 0, 0, 15, 100, false, false, false),
			RouteStage.MIX_FISH_17);
		assertEquals(RouteTarget.COOK, route.getTarget(snapshot(8, 0, 0, 15, 100, false, false, false)));
		updateAndAssert(route, snapshot(0, 8, 0, 15, 100, false, false, false),
			RouteStage.MIX_FISH_17);
		assertEquals(RouteTarget.FISH, route.getTarget(snapshot(0, 8, 0, 15, 100, false, false, false)));
		updateAndAssert(route, snapshot(9, 8, 0, 6, 100, false, false, false),
			RouteStage.MIX_COOK_17);
		updateAndAssert(route, snapshot(0, 17, 0, 6, 100, false, false, false),
			RouteStage.MIX_LOAD_17);
		updateAndAssert(route, loading(0, FIRST_HOPPER), RouteStage.MIX_FIRES_FIRST);
		assertEquals(RouteTarget.FISH, route.getTarget(snapshot(0, 0, 0, 23, 100, false, false, false)));
		updateAndAssert(route, snapshot(1, 0, 0, 22, 100, false, false, false),
			RouteStage.MIX_FISH_19_FIRST);

		completeFishCookLoad(route, 19, RouteStage.MIX_COOK_19_FIRST,
			RouteStage.MIX_LOAD_19_FIRST, RouteStage.MIX_ATTACK_FIRST, FIRST_HOPPER);
		closePoolAndAssert(route, RouteStage.MIX_FISH_19_SECOND);

		completeFishCookLoad(route, 19, RouteStage.MIX_COOK_19_SECOND,
			RouteStage.MIX_LOAD_19_SECOND, RouteStage.MIX_ATTACK_SECOND, FIRST_HOPPER);
		closePoolAndAssert(route, RouteStage.MIX_FISH_FINAL_28);

		updateAndAssert(route, snapshot(28, 0, 0, 0, 60, false, false, false),
			RouteStage.MIX_COOK_FINAL_28);
		updateAndAssert(route, snapshot(0, 28, 0, 0, 60, false, false, false),
			RouteStage.MIX_LOAD_FINAL_28);
		updateAndAssert(route, loading(14, FIRST_HOPPER), RouteStage.MIX_LOAD_FINAL_28);
		assertEquals(14, route.getFirstFinalHopperLoaded());
		assertFalse(route.isPreferredLoadHopper(FIRST_HOPPER));
		assertTrue(route.isPreferredLoadHopper(SECOND_HOPPER));
		updateAndAssert(route, loading(0, SECOND_HOPPER), RouteStage.MIX_ATTACK_FINAL);
		assertEquals(14, route.getSecondFinalHopperLoaded());

		updateAndAssert(route, snapshot(0, 0, 0, 28, 0, false, false, true),
			RouteStage.MIX_POST_KILL_BUCKETS);
		assertEquals(17, route.getStageNumber());
	}

	@Test
	public void doubleSpotEndsEarlyCookAndKeepsFishingPriority()
	{
		TemporossRoute route = new TemporossRoute(TemporossMethod.COOKING_MIX_XP_PERMITS);
		RouteSnapshot eightFish = snapshot(8, 0, 0, 15, 100, false, false, false);
		route.update(eightFish);
		assertEquals(RouteTarget.COOK, route.getTarget(eightFish));

		RouteSnapshot doubleSpot = snapshot(4, 4, 0, 15, 100, true, false, false);
		route.update(doubleSpot);
		assertEquals(RouteStage.MIX_FISH_17, route.getStage());
		assertEquals(RouteTarget.FISH, route.getTarget(doubleSpot));

		RouteSnapshot doubleGone = snapshot(9, 4, 0, 10, 100, false, false, false);
		route.update(doubleGone);
		assertEquals(RouteTarget.FISH, route.getTarget(doubleGone));
	}

	@Test
	public void firstThreeFishingTripsUseTheEarlyCookBreak()
	{
		RouteStage[] fishingStages =
		{
			RouteStage.MIX_FISH_17,
			RouteStage.MIX_FISH_19_FIRST,
			RouteStage.MIX_FISH_19_SECOND
		};
		for (RouteStage fishingStage : fishingStages)
		{
			TemporossRoute route = routeAt(fishingStage);
			RouteSnapshot eightFish = snapshot(8, 0, 0, 20, 100, false, false, false);
			route.update(eightFish);
			assertEquals(RouteTarget.COOK, route.getTarget(eightFish));

			RouteSnapshot doubleSpot = snapshot(4, 4, 0, 20, 100, true, false, false);
			route.update(doubleSpot);
			assertEquals(RouteTarget.FISH, route.getTarget(doubleSpot));
		}
	}

	@Test
	public void finalFishingCooksAfterDoubleExpiresAndReturnsToFishing()
	{
		TemporossRoute route = routeAt(RouteStage.MIX_FISH_FINAL_28);
		RouteSnapshot beforeDouble = snapshot(8, 0, 0, 20, 60, false, false, false);
		route.update(beforeDouble);
		assertEquals(RouteTarget.FISH, route.getTarget(beforeDouble));

		RouteSnapshot doubleActive = snapshot(12, 0, 0, 16, 60, true, false, false);
		route.update(doubleActive);
		assertEquals(RouteTarget.FISH, route.getTarget(doubleActive));

		RouteSnapshot doubleExpired = snapshot(12, 0, 0, 16, 60, false, false, false);
		route.update(doubleExpired);
		assertEquals(RouteTarget.COOK, route.getTarget(doubleExpired));

		RouteSnapshot cookedAfterDouble = snapshot(0, 12, 0, 16, 60, false, false, false);
		route.update(cookedAfterDouble);
		assertEquals(RouteTarget.FISH, route.getTarget(cookedAfterDouble));

		RouteSnapshot nextDouble = snapshot(4, 12, 0, 12, 60, true, false, false);
		route.update(nextDouble);
		assertEquals(RouteTarget.FISH, route.getTarget(nextDouble));
		RouteSnapshot nextDoubleExpired = snapshot(6, 12, 0, 10, 60, false, false, false);
		route.update(nextDoubleExpired);
		assertEquals(RouteTarget.COOK, route.getTarget(nextDoubleExpired));
	}

	@Test
	public void crystallisedFishDoesNotCountTowardCookingTargets()
	{
		TemporossRoute route = new TemporossRoute(TemporossMethod.COOKING_MIX_XP_PERMITS);
		route.update(snapshot(7, 0, 1, 15, 100, false, false, false));
		assertEquals(RouteTarget.FISH, route.getTarget(snapshot(7, 0, 1, 15, 100, false, false, false)));

		route.update(snapshot(8, 0, 1, 14, 100, false, false, false));
		assertEquals(RouteTarget.COOK, route.getTarget(snapshot(8, 0, 1, 14, 100, false, false, false)));
		route.update(snapshot(0, 8, 1, 14, 100, false, false, false));
		route.update(snapshot(13, 0, 4, 6, 100, false, false, false));
		assertEquals(RouteStage.MIX_FISH_17, route.getStage());
		route.update(snapshot(17, 0, 4, 2, 100, false, false, false));
		assertEquals(RouteStage.MIX_COOK_17, route.getStage());
	}

	@Test
	public void exactCookedThresholdsDoNotAdvanceEarly()
	{
		TemporossRoute route = routeAt(RouteStage.MIX_COOK_17);
		route.update(snapshot(0, 16, 0, 12, 100, false, false, false));
		assertEquals(RouteStage.MIX_COOK_17, route.getStage());
		route.update(snapshot(0, 17, 0, 11, 100, false, false, false));
		assertEquals(RouteStage.MIX_LOAD_17, route.getStage());

		TemporossRoute standard = routeAt(RouteStage.MIX_COOK_19_FIRST);
		standard.update(snapshot(0, 18, 0, 10, 100, false, false, false));
		assertEquals(RouteStage.MIX_COOK_19_FIRST, standard.getStage());
		standard.update(snapshot(0, 19, 0, 9, 100, false, false, false));
		assertEquals(RouteStage.MIX_LOAD_19_FIRST, standard.getStage());
	}

	@Test
	public void excessCatchPausesTargetUntilExtraFishIsRemoved()
	{
		TemporossRoute route = routeAt(RouteStage.MIX_FISH_17);
		RouteSnapshot eighteenFish = snapshot(18, 0, 0, 10, 100, false, false, false);

		route.update(eighteenFish);
		assertEquals(RouteStage.MIX_FISH_17, route.getStage());
		assertEquals(RouteTarget.NONE, route.getTarget(eighteenFish));
		assertEquals(1, route.getExcessFish(eighteenFish));

		route.update(snapshot(17, 0, 0, 11, 100, false, false, false));
		assertEquals(RouteStage.MIX_COOK_17, route.getStage());
	}

	@Test
	public void onlyConfirmedHopperLoadingAdvancesCookedLoad()
	{
		TemporossRoute route = routeAt(RouteStage.MIX_COOK_17);
		route.update(snapshot(0, 17, 0, 11, 100, false, false, false));
		assertEquals(RouteStage.MIX_LOAD_17, route.getStage());

		route.update(snapshot(0, 0, 0, 28, 100, false, false, false));
		assertEquals(RouteStage.MIX_LOAD_17, route.getStage());
		assertEquals(0, route.getPreparedLoadedThisStage());

		TemporossRoute confirmed = routeAt(RouteStage.MIX_COOK_17);
		confirmed.update(snapshot(0, 17, 0, 11, 100, false, false, false));
		confirmed.update(loading(10, FIRST_HOPPER));
		assertEquals(7, confirmed.getPreparedLoadedThisStage());
		confirmed.update(loading(0, FIRST_HOPPER));
		assertEquals(RouteStage.MIX_FIRES_FIRST, confirmed.getStage());
	}

	@Test
	public void postKillBucketSnapshotReportsCollectedAndFilledSeparately()
	{
		RouteSnapshot snapshot = new RouteSnapshot(
			0, 0, 0, 23, 0, false, false, false, -1, 3, 2, true);

		assertEquals(3, snapshot.getWaterBuckets());
		assertEquals(5, snapshot.getTotalBuckets());
	}

	@Test
	public void methodSwitchAndNavigationUseTheSeventeenStepRoute()
	{
		TemporossRoute route = new TemporossRoute();
		route.next();
		assertEquals(RouteStage.LOAD_26, route.getStage());

		route.setMethod(TemporossMethod.COOKING_MIX_XP_PERMITS);
		assertEquals(RouteStage.MIX_FISH_17, route.getStage());
		assertEquals(1, route.getStageNumber());
		assertEquals(17, route.getStageCount());

		route.previous();
		assertEquals(RouteStage.MIX_FISH_17, route.getStage());
		for (int i = 0; i < route.getStageCount() + 2; i++)
		{
			route.next();
		}
		assertEquals(RouteStage.MIX_POST_KILL_BUCKETS, route.getStage());
		assertEquals("No cooking (max XP)", TemporossMethod.NO_COOKING_MAX_XP.toString());
		assertEquals("Cooking Mix of XP and permits", TemporossMethod.COOKING_MIX_XP_PERMITS.toString());
	}

	@Test
	public void usesRequestedVisibleStepWording()
	{
		String[] titles =
		{
			"Fish 17 harpoonfish",
			"Cook all the fish",
			"Load all 17 fish",
			"Fires should come up now",
			"Fish 19 harpoonfish",
			"Cook all",
			"Load all 19 fish",
			"Attack Tempoross",
			"Fish 19 harpoonfish",
			"Cook all",
			"Load all 19 fish",
			"Attack Tempoross",
			"Fish 28 harpoonfish",
			"Cook all",
			"Load 14 in EACH cannon",
			"Attack Tempoross",
			"Take & fill 5 buckets"
		};

		TemporossRoute route = new TemporossRoute(TemporossMethod.COOKING_MIX_XP_PERMITS);
		for (int i = 0; i < titles.length; i++)
		{
			assertEquals(titles[i], route.getStage().getTitle());
			route.next();
		}

		assertEquals(
			"Cook when you've caught the first 8 or so, until a double fish spot comes up.",
			routeAt(RouteStage.MIX_FISH_17).getStage().getInstruction());
		assertEquals(
			"Fish until a double fish spot comes up, cook after it expires, and fish the double spot again when it spawns.",
			routeAt(RouteStage.MIX_FISH_FINAL_28).getStage().getInstruction());
		assertEquals(
			"Load 14 fish into first cannon.",
			routeAt(RouteStage.MIX_LOAD_FINAL_28).getStage().getInstruction());
		assertEquals(
			"Take 5 buckets and fill them with water before getting kicked out.",
			routeAt(RouteStage.MIX_POST_KILL_BUCKETS).getStage().getInstruction());
	}

	private static void completeFishCookLoad(
		TemporossRoute route,
		int target,
		RouteStage cookStage,
		RouteStage loadStage,
		RouteStage nextStage,
		int hopperKey)
	{
		updateAndAssert(route, snapshot(target, 0, 0, 28 - target, 70, false, false, false), cookStage);
		updateAndAssert(route, snapshot(0, target, 0, 28 - target, 70, false, false, false), loadStage);
		updateAndAssert(route, loading(0, hopperKey), nextStage);
	}

	private static void closePoolAndAssert(TemporossRoute route, RouteStage expected)
	{
		route.update(snapshot(0, 0, 0, 28, 70, false, true, false));
		updateAndAssert(route, snapshot(0, 0, 0, 28, 70, false, false, false), expected);
	}

	private static TemporossRoute routeAt(RouteStage target)
	{
		TemporossRoute route = new TemporossRoute(TemporossMethod.COOKING_MIX_XP_PERMITS);
		while (route.getStage() != target)
		{
			route.next();
		}
		return route;
	}

	private static RouteSnapshot loading(int cooked, int hopperKey)
	{
		return new RouteSnapshot(
			0, cooked, 0, 28 - cooked, 70, false, false, true, hopperKey, 0, 0, false);
	}

	private static RouteSnapshot snapshot(
		int raw,
		int cooked,
		int crystallised,
		int freeSlots,
		Integer essence,
		boolean doubleSpot,
		boolean poolActive,
		boolean defeated)
	{
		return new RouteSnapshot(
			raw,
			cooked,
			crystallised,
			freeSlots,
			essence,
			doubleSpot,
			poolActive,
			false,
			defeated);
	}

	private static void updateAndAssert(
		TemporossRoute route,
		RouteSnapshot snapshot,
		RouteStage expected)
	{
		route.update(snapshot);
		assertEquals(expected, route.getStage());
	}
}

package com.temporosssolo;

import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TemporossWorkingSideTest
{
	private static final int WORLD_VIEW = 0;
	private static final LocalPoint WEST_SOUTH = point(512, 512);
	private static final LocalPoint WEST_NORTH = point(512, 768);
	private static final LocalPoint EAST_SOUTH = point(2816, 512);
	private static final LocalPoint EAST_NORTH = point(2816, 768);

	@Test
	public void splitsIslandShoreAcrossBothShips()
	{
		TemporossWorkingSide side = standardArena();

		side.observeCandidate(WEST_SOUTH);
		assertFalse(side.isKnown());
		assertFalse(side.contains(point(512, 0)));
		assertTrue(side.confirmCandidate());

		assertTrue(side.contains(point(512, 0)));
		assertTrue(side.contains(point(2816, 0)));
		assertFalse(side.contains(point(512, 1280)));
		assertFalse(side.contains(point(2816, 1280)));
		assertFalse(side.contains(point(1664, 640)));
	}

	@Test
	public void remainsUnknownUntilAllFourCratesAreKnown()
	{
		TemporossWorkingSide side = sideWithCrates(WEST_SOUTH, WEST_NORTH);

		side.observeCandidate(WEST_SOUTH);
		assertFalse(side.confirmCandidate());
		assertFalse(side.contains(point(512, 0)));

		side.rememberCrate(EAST_SOUTH);
		side.rememberCrate(EAST_NORTH);
		assertTrue(side.isKnown());
		assertTrue(side.contains(point(2816, 0)));
	}

	@Test
	public void successfulLoadLocksTheExactShoreUntilReset()
	{
		TemporossWorkingSide side = sideWithCrates(
			EAST_NORTH,
			WEST_SOUTH,
			EAST_SOUTH,
			WEST_NORTH);

		side.observeCandidate(EAST_NORTH);
		assertTrue(side.confirmCandidate());
		side.observeCandidate(WEST_SOUTH);
		assertTrue(side.confirmCandidate());
		assertTrue(side.contains(point(512, 1280)));
		assertTrue(side.contains(point(2816, 1280)));
		assertFalse(side.contains(point(512, 0)));
		assertFalse(side.contains(point(2816, 0)));

		side.reset();
		assertFalse(side.isKnown());
		assertFalse(side.contains(point(2816, 1280)));
	}

	@Test
	public void shoreSplitSurvivesRotationAndTranslation()
	{
		LocalPoint westSouth = point(2000, 1000);
		LocalPoint westNorth = point(1744, 1000);
		LocalPoint eastSouth = point(2000, 3304);
		LocalPoint eastNorth = point(1744, 3304);
		TemporossWorkingSide side = sideWithCrates(
			eastNorth,
			westSouth,
			westNorth,
			eastSouth);

		side.observeCandidate(westSouth);
		assertTrue(side.confirmCandidate());
		assertTrue(side.contains(point(2512, 1000)));
		assertTrue(side.contains(point(2512, 3304)));
		assertFalse(side.contains(point(1232, 1000)));
		assertFalse(side.contains(point(1232, 3304)));
		assertFalse(side.contains(point(1872, 2152)));
	}

	private static TemporossWorkingSide standardArena()
	{
		return sideWithCrates(WEST_SOUTH, WEST_NORTH, EAST_SOUTH, EAST_NORTH);
	}

	private static TemporossWorkingSide sideWithCrates(LocalPoint... crates)
	{
		TemporossWorkingSide side = new TemporossWorkingSide();
		for (LocalPoint crate : crates)
		{
			side.rememberCrate(crate);
		}
		return side;
	}

	private static LocalPoint point(int x, int y)
	{
		return new LocalPoint(x, y, WORLD_VIEW);
	}
}

package com.temporosssolo;

import org.junit.Test;

