public interface TemporossSoloHelperConfig extends Config
{
	String GROUP = "tempoross-solo-helper";

	@ConfigItem(
		keyName = "method",
		name = "Method",
		description = "Selects the solo Tempoross strategy to guide"
	)
	default TemporossMethod method()
	{
		return TemporossMethod.NO_COOKING_MAX_XP;
	}

	@ConfigItem(
		keyName = "showPanel",
		name = "Show route panel",
		description = "Shows the current solo route step and progress"
	)
	default boolean showPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightTargets",
		name = "Highlight current target",
		description = "Highlights the current route target and active fires on the working shore"
	)
	default boolean highlightTargets()
	{
		return true;
	}

	@ConfigItem(
		keyName = "autoAdvance",
		name = "Auto-advance steps",
		description = "Advances the route from inventory, spirit-pool, and HUD state"
	)
	default boolean autoAdvance()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Target color",
		description = "Color used for the current route target"
	)
	default Color highlightColor()
	{
		return new Color(0, 255, 255, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "priorityColor",
		name = "Double-spot color",
		description = "Color used for priority double-fish spots"
	)
	default Color priorityColor()
	{
		return new Color(255, 215, 0, 230);
	}

	@Alpha
	@ConfigItem(
		keyName = "urgentColor",
		name = "Fire color",
		description = "Color used to highlight active fires"
	)
	default Color urgentColor()
	{
		return new Color(255, 170, 0, 230);
	}

	@ConfigItem(
		keyName = "nextStep",
		name = "Next-step hotkey",
		description = "Moves to the next route step; the panel also has a right-click action"
	)
	default Keybind nextStep()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "previousStep",
		name = "Previous-step hotkey",
		description = "Moves to the previous route step; the panel also has a right-click action"
	)
	default Keybind previousStep()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "resetRoute",
		name = "Reset-route hotkey",
		description = "Returns the selected method to its first step; the panel also has a right-click action"
	)
	default Keybind resetRoute()
	{
		return Keybind.NOT_SET;
	}
}

package com.temporosssolo;

final class RouteSnapshot
{
	private final int rawFish;
	private final int cookedFish;
	private final int crystallisedFish;
	private final int freeInventorySlots;
	private final Integer essencePercent;
	private final boolean doubleSpotActive;
	private final boolean spiritPoolActive;
	private final boolean loadingFish;
	private final int loadingHopperKey;
	private final int waterBuckets;
	private final int emptyBuckets;
	private final boolean defeated;

	RouteSnapshot(
		int rawFish,
		int cookedFish,
		int crystallisedFish,
		int freeInventorySlots,
		Integer essencePercent,
		boolean doubleSpotActive,
		boolean spiritPoolActive,
		boolean loadingFish,
		boolean defeated)
	{
		this(
			rawFish,
			cookedFish,
			crystallisedFish,
			freeInventorySlots,
			essencePercent,
			doubleSpotActive,
			spiritPoolActive,
			loadingFish,
			-1,
			0,
			0,
			defeated);
	}

	RouteSnapshot(
		int rawFish,
		int cookedFish,
		int crystallisedFish,
		int freeInventorySlots,
		Integer essencePercent,
		boolean doubleSpotActive,
		boolean spiritPoolActive,
		boolean loadingFish,
		int loadingHopperKey,
		int waterBuckets,
		int emptyBuckets,
		boolean defeated)
	{
		this.rawFish = rawFish;
		this.cookedFish = cookedFish;
		this.crystallisedFish = crystallisedFish;
		this.freeInventorySlots = freeInventorySlots;
		this.essencePercent = essencePercent;
		this.doubleSpotActive = doubleSpotActive;
		this.spiritPoolActive = spiritPoolActive;
		this.loadingFish = loadingFish;
		this.loadingHopperKey = loadingHopperKey;
		this.waterBuckets = waterBuckets;
		this.emptyBuckets = emptyBuckets;
		this.defeated = defeated;
	}

	int getRawFish()
	{
		return rawFish;
	}

	int getCookedFish()
	{
		return cookedFish;
	}

	int getPreparedFish()
	{
		return cookedFish;
	}

	int getCookableFish()
	{
		return rawFish + cookedFish;
	}

	int getTotalFish()
	{
		return rawFish + cookedFish + crystallisedFish;
	}

	int getFishCapacity()
	{
		return getTotalFish() + freeInventorySlots;
	}

	int getCookableFishCapacity()
	{
		return getCookableFish() + freeInventorySlots;
	}

	Integer getEssencePercent()
	{
		return essencePercent;
	}

	boolean isDoubleSpotActive()
	{
		return doubleSpotActive;
	}

	boolean isSpiritPoolActive()
	{
		return spiritPoolActive;
	}

	boolean isLoadingFish()
	{
		return loadingFish;
	}

	int getLoadingHopperKey()
	{
		return loadingHopperKey;
	}

	int getWaterBuckets()
	{
		return waterBuckets;
	}

	int getTotalBuckets()
	{
		return waterBuckets + emptyBuckets;
	}

	boolean isDefeated()
	{
		return defeated;
	}
}

