package com.temporosssolo;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.LocalPoint;

final class TemporossWorkingSide
{
	private final List<LocalPoint> ammunitionCrates = new ArrayList<>();
	private LocalPoint candidateCrate;
	private LocalPoint confirmedCrate;
	private LocalPoint oppositeShoreCrate;

	void reset()
	{
		ammunitionCrates.clear();
		candidateCrate = null;
		confirmedCrate = null;
		oppositeShoreCrate = null;
	}

	void rememberCrate(LocalPoint crate)
	{
		if (crate != null && !ammunitionCrates.contains(crate))
		{
			ammunitionCrates.add(crate);
			rebuildConfirmedPair();
		}
	}

	void observeCandidate(LocalPoint crate)
	{
		if (confirmedCrate == null && crate != null)
		{
			candidateCrate = crate;
		}
	}

	LocalPoint getCandidate()
	{
		return candidateCrate;
	}

	boolean confirmCandidate()
	{
		if (confirmedCrate == null)
		{
			confirmedCrate = candidateCrate;
			rebuildConfirmedPair();
		}
		return isKnown();
	}

	boolean isKnown()
	{
		return confirmedCrate != null
			&& oppositeShoreCrate != null
			&& ammunitionCrates.size() >= 4;
	}

	boolean contains(LocalPoint location)
	{
		if (location == null || !isKnown())
		{
			return false;
		}

		// The nearest other hopper is the opposite-shore endpoint on the same
		// ship. Projecting across their midpoint splits the entire arena by island
		// shoreline instead of incorrectly splitting it by left/right ship. A fire
		// exactly on the center line is ignored.
		long shoreAxisX = (long) confirmedCrate.getX() - oppositeShoreCrate.getX();
		long shoreAxisY = (long) confirmedCrate.getY() - oppositeShoreCrate.getY();
		long relativeXTwice = 2L * location.getX() - confirmedCrate.getX() - oppositeShoreCrate.getX();
		long relativeYTwice = 2L * location.getY() - confirmedCrate.getY() - oppositeShoreCrate.getY();
		return relativeXTwice * shoreAxisX + relativeYTwice * shoreAxisY > 0;
	}

	private void rebuildConfirmedPair()
	{
		if (confirmedCrate == null || ammunitionCrates.size() < 4)
		{
			oppositeShoreCrate = null;
			return;
		}

		oppositeShoreCrate = null;
		int oppositeShoreDistance = Integer.MAX_VALUE;
		for (LocalPoint crate : ammunitionCrates)
		{
			if (crate.equals(confirmedCrate))
			{
				continue;
			}

			int distance = confirmedCrate.distanceTo(crate);
			if (distance < oppositeShoreDistance)
			{
				oppositeShoreDistance = distance;
				oppositeShoreCrate = crate;
			}
		}
	}
}

package com.temporosssolo;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class TemporossSoloSceneOverlay extends Overlay
{
	private static final BasicStroke TARGET_STROKE = new BasicStroke(3f);

	private final Client client;
	private final TemporossSoloHelperPlugin plugin;
	private final TemporossSoloHelperConfig config;

	@Inject
	private TemporossSoloSceneOverlay(
		Client client,
		TemporossSoloHelperPlugin plugin,
		TemporossSoloHelperConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightTargets() || !plugin.isInEncounter())
		{
			return null;
		}

		switch (plugin.getTarget())
		{
			case NONE:
				break;
			case FISH:
				renderFishingSpot(graphics);
				break;
			case COOK:
				renderObject(graphics, nearestObject(TemporossSoloHelperPlugin.COOKING_SHRINE_IDS),
					"Cook fish", config.highlightColor());
				break;
			case LOAD:
				renderNpc(graphics, nearestLoadTarget(),
					"Load fish", config.highlightColor());
				break;
			case ATTACK:
				renderNpc(graphics, nearestNpc(TemporossSoloHelperPlugin.SPIRIT_POOL_IDS),
					"Harpoon Tempoross", config.highlightColor());
				break;
			case LEAVE:
				renderNpc(graphics, nearestNpc(TemporossSoloHelperPlugin.VICTORY_NPC_IDS),
					"Leave", config.highlightColor());
				break;
		}

		renderFire(graphics, "Douse", config.urgentColor());
		return null;
	}

	private void renderFishingSpot(Graphics2D graphics)
	{
		NPC doubleSpot = nearestNpc(TemporossSoloHelperPlugin.DOUBLE_FISHING_SPOT_IDS);
		if (doubleSpot != null)
		{
			renderNpc(graphics, doubleSpot, "Double fish", config.priorityColor());
			return;
		}

		renderNpc(graphics, nearestNpc(TemporossSoloHelperPlugin.FISHING_SPOT_IDS),
			"Fish", config.highlightColor());
	}

	private void renderFire(Graphics2D graphics, String label, Color color)
	{
		NPC fireNpc = nearestNpc(TemporossSoloHelperPlugin.FIRE_NPC_IDS, true);
		if (fireNpc != null)
		{
			renderNpc(graphics, fireNpc, label, color);
			return;
		}
		renderObject(graphics, nearestObject(TemporossSoloHelperPlugin.FIRE_OBJECT_IDS, true), label, color);
	}

	private GameObject nearestObject(Set<Integer> ids)
	{
		return nearestObject(ids, false);
	}

	private GameObject nearestObject(Set<Integer> ids, boolean workingSideOnly)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		GameObject nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (GameObject object : plugin.getTrackedObjects())
		{
			if (!ids.contains(object.getId())
				|| object.getPlane() != player.getWorldLocation().getPlane()
				|| (workingSideOnly && !plugin.isOnWorkingSide(object.getLocalLocation())))
			{
				continue;
			}
			int distance = object.getLocalLocation().distanceTo(player.getLocalLocation());
			if (distance < nearestDistance)
			{
				nearestDistance = distance;
				nearest = object;
			}
		}
		return nearest;
	}

	private NPC nearestNpc(Set<Integer> ids)
	{
		return nearestNpc(ids, false);
	}

	private NPC nearestLoadTarget()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		NPC nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (NPC npc : plugin.getTrackedNpcs())
		{
			if (!TemporossSoloHelperPlugin.AMMUNITION_CRATE_IDS.contains(npc.getId())
				|| !plugin.isPreferredLoadTarget(npc))
			{
				continue;
			}
			int distance = npc.getLocalLocation().distanceTo(player.getLocalLocation());
			if (distance < nearestDistance)
			{
				nearestDistance = distance;
				nearest = npc;
			}
		}
		return nearest;
	}

	private NPC nearestNpc(Set<Integer> ids, boolean workingSideOnly)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		NPC nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (NPC npc : plugin.getTrackedNpcs())
		{
			if (!ids.contains(npc.getId())
				|| (workingSideOnly && !plugin.isOnWorkingSide(npc.getLocalLocation())))
			{
				continue;
			}
			int distance = npc.getLocalLocation().distanceTo(player.getLocalLocation());
			if (distance < nearestDistance)
			{
				nearestDistance = distance;
				nearest = npc;
			}
		}
		return nearest;
	}

	private void renderObject(Graphics2D graphics, GameObject object, String label, Color color)
	{
		if (object == null)
		{
			return;
		}

		Shape shape = object.getClickbox();
		if (shape == null)
		{
			shape = object.getConvexHull();
		}
		if (shape == null)
		{
			shape = object.getCanvasTilePoly();
		}
		if (shape != null)
		{
			OverlayUtil.renderPolygon(graphics, shape, color, fill(color), TARGET_STROKE);
		}
		Point textLocation = object.getCanvasTextLocation(graphics, label, 40);
		if (textLocation != null)
		{
			OverlayUtil.renderTextLocation(graphics, textLocation, label, color);
		}
	}

	private void renderNpc(Graphics2D graphics, NPC npc, String label, Color color)
	{
		if (npc == null)
		{
			return;
		}

		Shape shape = npc.getConvexHull();
		if (shape == null)
		{
			shape = npc.getCanvasTilePoly();
		}
		if (shape != null)
		{
			OverlayUtil.renderPolygon(graphics, shape, color, fill(color), TARGET_STROKE);
		}
		Point textLocation = npc.getCanvasTextLocation(graphics, label, npc.getLogicalHeight() + 40);
		if (textLocation != null)
		{
			OverlayUtil.renderTextLocation(graphics, textLocation, label, color);
		}
	}

	private static Color fill(Color color)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), 55);
	}
}
